const extraMuscleLabels={infraspinatus:'Infraespinoso',latissimus:'Dorsal ancho',pronators:'Pronador redondo y pronador cuadrado',wristflexors:'Flexores de muñeca',wristextensors:'Extensores de muñeca',deepneck:'Flexores y extensores cervicales profundos',neckmuscles:'Esternocleidomastoideo y esplenios',suprahyoid:'Músculos suprahioideos',deltoid:'Deltoides',biceps:'Bíceps y braquial',quadriceps:'Cuádriceps',gluteusmaximus:'Glúteo mayor',iliopsoas:'Iliopsoas',hamstrings:'Isquiotibiales',triceps:'Tríceps braquial',soleus:'Sóleo'};
const bilateralExamples=new Set(['sitdown','standup','walkstep','curl','tricepsext','lateralraise','overheadpress','row','lunge','heelraise','deadlift','runstride','swimcrawl','basketshot','cycling','chestpress','pullup','rdl']);
const sportReferences={runstride:'sportrun',footballkick:'sportfootball',tennisserve:'sporttennis',swimcrawl:'sportswim',basketshot:'sportbasket',cycling:'sportcycling'};
for(const example of extraMovements){
  const base=movements.find(m=>m.id===example.base);
  const movement={...base,...example,category:example.category,sources:[...new Set([...base.sources,'motions','levers',...(sportReferences[example.id]?[sportReferences[example.id]]:[]),...(example.category==='Entrenamiento'?['motorunits','heavyload']:[]),...(example.id==='rdl'?['rdlstudy']:[])])],
    side:bilateralExamples.has(example.id)?'both':example.side||'R',
    joint:example.joint||base.joint.replace(/plano (sagital|frontal|transversal)/,`plano ${example.plane}`),
    muscle:example.muscle||extraMuscleLabels[example.highlight]||base.muscle,
    origin:example.origin||(example.highlight===base.highlight?base.origin:'Varía entre los músculos participantes; selecciona la malla individual para estudiar sus relaciones óseas.'),
    insertion:example.insertion||(example.highlight===base.highlight?base.insertion:'Varía entre los músculos participantes; esta secuencia muestra su función global.')};
  movements.push(movement);
  biomechanics[example.id]={
    axis:`Predomina el ${planes[example.plane].name.toLowerCase()}. En un gesto real pueden intervenir otros planos y traslaciones que este visor no resuelve.`,
    synergy:example.muscles,
    control:example.observe
  };
}

