  {id:'sacrum',name:'Sacro',type:'HUESO',text:'Hueso triangular de vértebras fusionadas en la base de la columna. Se articula con los huesos coxales y transmite carga hacia la pelvis.',fact:'La pieza central posterior de la pelvis representa su ubicación aproximada.',sources:['spine','pelvis']},
  {id:'radius',name:'Radio',type:'HUESO',text:'Hueso lateral del antebrazo en posición anatómica, del lado del pulgar. Su tuberosidad recibe el tendón del bíceps y su extremo distal participa en la muñeca.',fact:'En el visor es la varilla del lado del pulgar; no se anima la pronación.',sources:['upperbones','forearmbones']},
  {id:'ulna',name:'Cúbito',type:'HUESO',text:'Hueso medial del antebrazo, también llamado ulna. Su olécranon forma la punta del codo y la escotadura troclear se articula con el húmero.',fact:'Se representa paralelo al radio en una postura fija del antebrazo.',sources:['upperbones','forearmbones']},
  {id:'carpals',name:'Huesos del carpo',type:'HUESOS',text:'Ocho huesos pequeños organizados en dos filas forman la base de la mano. Entre ellos están escafoides, semilunar, piramidal y pisiforme.',fact:'Aquí se ven como dos filas de pequeñas piezas; sus superficies reales se simplifican.',sources:['upperbones','handbones']},
  {id:'metacarpals',name:'Metacarpianos',type:'HUESOS',text:'Cinco huesos largos forman la palma, entre el carpo y las falanges. El primero corresponde al pulgar.',fact:'Cada varilla de la palma es una referencia de un metacarpiano.',sources:['upperbones','handbones']},
  {id:'handphalanges',name:'Falanges de la mano',type:'HUESOS',text:'Los dedos y el pulgar contienen catorce falanges por mano: dos en el pulgar y tres en cada uno de los otros dedos.',fact:'Las falanges visibles son segmentos separados; la flexión de los dedos no está animada.',sources:['upperbones','handbones']},
  {id:'tibia',name:'Tibia',type:'HUESO',text:'Hueso medial y principal portador de carga de la pierna. Sus cóndilos reciben el fémur y su extremo distal forma el maléolo medial.',fact:'Es la varilla más gruesa de la pierna en el visor.',sources:['lowerbones','legbones']},
  {id:'fibula',name:'Fíbula o peroné',type:'HUESO',text:'Hueso lateral y más delgado de la pierna. Su extremo distal forma el maléolo lateral del tobillo.',fact:'Aparece junto a la tibia, sin reproducir todas las articulaciones tibioperoneas.',sources:['lowerbones','legbones']},
  {id:'talus',name:'Talo',type:'HUESO',text:'Hueso superior del retropié que recibe la tibia y la fíbula en la articulación talocrural y se apoya sobre el calcáneo.',fact:'La pieza superior del pie marca su región; la forma articular es esquemática.',sources:['lowerbones','talus']},
  {id:'calcaneus',name:'Calcáneo',type:'HUESO',text:'Hueso grande del talón, situado debajo del talo. Recibe el tendón calcáneo del tríceps sural.',fact:'La pieza posterior e inferior señala el talón.',sources:['lowerbones','footbones']},
  {id:'metatarsals',name:'Metatarsianos',type:'HUESOS',text:'Cinco huesos largos conectan el tarso con las falanges de los dedos del pie y contribuyen al antepié.',fact:'Se muestran como cinco rayos separados.',sources:['lowerbones','footbones']},
  {id:'toephalanges',name:'Falanges del pie',type:'HUESOS',text:'Los dedos del pie tienen catorce falanges por lado: dos en el dedo gordo y tres en cada uno de los otros dedos.',fact:'Se representan como segmentos cortos, sin movimiento individual.',sources:['lowerbones','footbones']},
  {id:'wristjoint',name:'Articulación de la muñeca',type:'ARTICULACIÓN',text:'La articulación radiocarpiana relaciona el radio distal y el complejo fibrocartilaginoso con la fila proximal del carpo. Contribuye a flexión, extensión y desviaciones.',fact:'El punto luminoso señala la región de la muñeca; no hay animación específica.',sources:['upperbones','joints']},
  {id:'trapezius',name:'Trapecio',type:'MÚSCULO',text:'Músculo superficial del cuello y espalda superior. Sus fibras llegan desde cráneo y columna a clavícula, acromion y espina de la escápula.',fact:'Participa en elevación, retracción y rotación de la escápula según la porción activa.',sources:['upperlimb','shoulderabductors']},
  {id:'serratus',name:'Serrato anterior',type:'MÚSCULO',text:'Nace mediante digitaciones en las costillas superiores y llega a la cara anterior del borde medial de la escápula.',fact:'Ayuda a llevar la escápula hacia delante y a rotarla durante la elevación del brazo.',sources:['upperlimb','shoulderabductors']},
  {id:'latissimus',name:'Dorsal ancho',type:'MÚSCULO',text:'Amplio músculo de la espalda inferior con inserción en el húmero. Contribuye a extensión, aducción y rotación medial del brazo.',fact:'La lámina posterior del visor solo indica su territorio superficial.',sources:['upperlimb','latissimus']},
  {id:'rectusabdominis',name:'Recto del abdomen',type:'MÚSCULO',text:'Par muscular vertical de la pared abdominal anterior, desde pubis hasta cartílagos costales y apófisis xifoides.',fact:'Contribuye a flexión del tronco y control de la pelvis; se muestran dos bandas.',sources:['axialmuscles','rectus']},
  {id:'brachialis',name:'Braquial',type:'MÚSCULO',text:'Se origina en la cara anterior distal del húmero y termina en la tuberosidad y apófisis coronoides del cúbito.',fact:'Flexor importante del codo, profundo al bíceps.',sources:['upperlimb','biceps2']},
  {id:'gluteusmaximus',name:'Glúteo mayor',type:'MÚSCULO',text:'Músculo posterior voluminoso de la cadera que se origina en pelvis y sacro; termina en el tracto iliotibial y la tuberosidad glútea del fémur.',fact:'Potente extensor de cadera; su volumen se dibuja detrás de la pelvis.',sources:['limbmuscles','gluteus2']},
  {id:'soleus',name:'Sóleo',type:'MÚSCULO',text:'Músculo profundo de la pantorrilla que nace en tibia y fíbula y converge con el gastrocnemio hacia el tendón calcáneo.',fact:'Participa en la flexión plantar y el control del tobillo en apoyo.',sources:['limbmuscles','gastrocnemius2']},
  {id:'cervical',name:'Vértebras cervicales',type:'HUESOS',text:'Las siete vértebras del cuello sostienen la cabeza y permiten gran movilidad. C1 y C2 tienen formas especializadas.',fact:'Se resaltan solo segmentos esquemáticos del cuello; su número y forma visibles no son anatómicamente exactos.',sources:['spine','vertebrae']},
  {id:'thoracic',name:'Vértebras torácicas',type:'HUESOS',text:'Doce vértebras forman la región posterior del tórax y se articulan con las costillas.',fact:'El visor las agrupa en el tramo medio de la columna, con menos piezas que las reales.',sources:['spine','vertebrae']},
  {id:'lumbar',name:'Vértebras lumbares',type:'HUESOS',text:'Cinco vértebras grandes forman la parte baja y móvil de la columna y soportan una parte importante de la carga axial.',fact:'El tramo bajo posterior muestra su posición aproximada, sin procesos óseos individuales.',sources:['spine','vertebrae']},
  {id:'ilium',name:'Ilion',type:'HUESO',text:'Región superior y ancha de cada hueso coxal. Su cresta es palpable y ofrece inserción a músculos abdominales y glúteos.',fact:'El arco superior de cada lado señala la cresta ilíaca.',sources:['pelvis','pelvis2']},
  {id:'ischium',name:'Isquion',type:'HUESO',text:'Región posteroinferior del hueso coxal. La tuberosidad isquiática soporta peso al sentarse y da origen a gran parte de los isquiotibiales.',fact:'Su porción inferior se marca cerca del borde posterior del foramen obturador.',sources:['pelvis','pelvis2']},
  {id:'pubis',name:'Pubis',type:'HUESO',text:'Región anteromedial del hueso coxal; ambos pubis se unen en la sínfisis púbica y contribuyen al contorno del foramen obturador.',fact:'El tramo anterior e interno de la pelvis muestra la región púbica.',sources:['pelvis','pelvis2']},
  {id:'navicular',name:'Navicular del pie',type:'HUESO',text:'Hueso medial del mediopié, situado por delante de la cabeza del talo y proximal a los cuneiformes.',fact:'Se distingue como una pequeña pieza medial delante del talo.',sources:['lowerbones','midfoot']},
  {id:'cuboid',name:'Cuboides',type:'HUESO',text:'Hueso lateral del mediopié, anterior al calcáneo y relacionado con los metatarsianos cuarto y quinto.',fact:'Su bloque lateral es una simplificación de la forma real.',sources:['lowerbones','midfoot']},
  {id:'cuneiforms',name:'Cuneiformes',type:'HUESOS',text:'Tres huesos del mediopié conectan principalmente el navicular con los primeros tres metatarsianos.',fact:'Se representan por tres pequeñas piezas contiguas.',sources:['lowerbones','midfoot']},
  {id:'supraspinatus',name:'Supraespinoso',type:'MÚSCULO',text:'Nace en la fosa supraespinosa de la escápula y se inserta en el tubérculo mayor del húmero. Ayuda al comienzo de la abducción y estabiliza la cabeza humeral.',fact:'La banda superior posterior indica su trayecto; no se deforma durante la animación.',sources:['upperlimb','rotatorcuff']},
  {id:'infraspinatus',name:'Infraespinoso',type:'MÚSCULO',text:'Nace en la fosa infraespinosa y llega al tubérculo mayor del húmero. Contribuye a la rotación lateral del brazo y a la estabilidad glenohumeral.',fact:'Se sitúa detrás de la escápula, bajo su espina.',sources:['upperlimb','rotatorcuff']},
  {id:'subscapularis',name:'Subescapular',type:'MÚSCULO',text:'Ocupa la cara anterior de la escápula y se inserta en el tubérculo menor del húmero. Participa en rotación medial y estabilidad del hombro.',fact:'La pieza profunda anterior solo señala su región.',sources:['upperlimb','rotatorcuff']},
  {id:'teresminor',name:'Redondo menor',type:'MÚSCULO',text:'Va del borde lateral de la escápula al tubérculo mayor del húmero. Ayuda a rotar lateralmente el brazo y forma parte del manguito rotador.',fact:'Se ve como una banda pequeña posterior e inferior al infraespinoso.',sources:['upperlimb','rotatorcuff']},
  {id:'rhomboids',name:'Romboides',type:'MÚSCULOS',text:'Músculos entre la columna y el borde medial de la escápula. Colaboran en su retracción y estabilización.',fact:'Las bandas oblicuas posteriores indican el grupo mayor y menor.',sources:['upperlimb','backmuscles']},
  {id:'externaloblique',name:'Oblicuo externo',type:'MÚSCULO',text:'Capa superficial de la pared abdominal lateral con fibras que descienden medialmente desde las costillas hacia la aponeurosis abdominal y la pelvis.',fact:'La lámina en cada flanco señala su dirección general, sin mostrar capas profundas.',sources:['axialmuscles','rectus']},
  {id:'erectorspinae',name:'Erectores espinales',type:'MÚSCULOS',text:'Grupo longitudinal profundo que recorre ambos lados de la columna y contribuye a extensión y control postural del tronco.',fact:'Dos columnas musculares posteriores indican el grupo sin diferenciar sus componentes.',sources:['backmuscles','backncbi']},
  {id:'brachioradialis',name:'Braquiorradial',type:'MÚSCULO',text:'Músculo superficial lateral del antebrazo, desde el húmero distal hasta el radio distal. Ayuda a flexionar el codo, especialmente con el antebrazo en posición neutra.',fact:'La banda lateral acompaña al antebrazo durante la flexión del codo.',sources:['upperlimb','brachioradialis']},
  {id:'forearmflexors',name:'Flexores del antebrazo',type:'MÚSCULOS',text:'Grupo anterior del antebrazo que mueve muñeca y dedos. Sus tendones se dirigen hacia la palma; aquí se muestra un volumen conjunto.',fact:'No se individualizan los tendones ni el túnel carpiano.',sources:['upperlimb','biceps2']},
  {id:'forearmextensors',name:'Extensores del antebrazo',type:'MÚSCULOS',text:'Grupo posterior del antebrazo cuyos tendones extienden muñeca y dedos. Se representa como una banda opuesta a los flexores.',fact:'La acción digital individual no está animada.',sources:['upperlimb','biceps2']},
  {id:'adductorlongus',name:'Aductor largo',type:'MÚSCULO',text:'Nace en el pubis y llega al tercio medio de la línea áspera del fémur. Contribuye a acercar el muslo a la línea media.',fact:'Su banda anterior y medial se mueve con el muslo en el visor.',sources:['limbmuscles','hipmuscles']},
  {id:'sartorius',name:'Sartorio',type:'MÚSCULO',text:'Músculo largo y superficial desde la espina ilíaca anterosuperior hasta la tibia medial proximal. Cruza cadera y rodilla.',fact:'La banda oblicua del muslo indica su recorrido, sin deformación muscular real.',sources:['limbmuscles','femoral']},
  {id:'tensorfasciae',name:'Tensor de la fascia lata',type:'MÚSCULO',text:'Músculo anterolateral corto de la cadera que tensa el tracto iliotibial; puede ayudar a flexión y abducción de cadera.',fact:'Se marca lateral al muslo proximal, sin dibujar todo el tracto.',sources:['limbmuscles','fascia']},
  {id:'gluteusminimus',name:'Glúteo menor',type:'MÚSCULO',text:'Músculo profundo de la cara externa del ilion que llega al trocánter mayor. Participa en abducción y estabilización de la pelvis.',fact:'Se ve como una pieza pequeña y profunda bajo el glúteo medio.',sources:['limbmuscles','hipmuscles']},
  {id:'tmjoint',name:'Articulación temporomandibular',type:'ARTICULACIÓN',text:'Une cada cóndilo mandibular con el hueso temporal. Combina rotación y traslación durante la apertura y cierre de la boca.',fact:'El control muestra solo una rotación inicial aproximada; la traslación del cóndilo y del disco no se simula.',sources:['mandible','tmj']},
  {id:'sacroiliac',name:'Articulación sacroilíaca',type:'ARTICULACIÓN',text:'Une el sacro con el ilion a cada lado. Sus ligamentos fuertes permiten transferencia de carga entre columna y pelvis con movilidad limitada.',fact:'El punto posterior señala la región; la movilidad sacroilíaca no se simula.',sources:['pelvis','pelvicjoints']},
  {id:'transverseforamen',name:'Foramen transversario',type:'ABERTURA ÓSEA',text:'Abertura en la apófisis transversa de las vértebras cervicales. Forma un trayecto para vasos vertebrales en la región del cuello.',fact:'El aro marca un nivel cervical aproximado; no es una perforación real del hueso 3D.',sources:['spine','vertebrae']},
  {id:'sacralforamina',name:'Forámenes sacros posteriores',type:'ABERTURA ÓSEA',text:'Pares de orificios en la superficie posterior del sacro por los que emergen ramas nerviosas sacras.',fact:'Se señalan algunos pares con aros; el sacro y sus aberturas no tienen geometría clínica exacta.',sources:['spine','sacralforamina']},
  {id:'pectoralisminor',name:'Pectoral menor',type:'MÚSCULO',text:'Músculo profundo al pectoral mayor que va de costillas superiores a la apófisis coracoides de la escápula.',fact:'Ayuda a estabilizar y descender la escápula; con la escápula fija puede colaborar en la inspiración.',sources:['upperlimb','bodyparts']},
  {id:'neckmuscles',name:'Esternocleidomastoideo y esplenio',type:'MÚSCULOS',text:'El esternocleidomastoideo ocupa el cuello anterolateral; el esplenio de la cabeza se sitúa en la región posterior.',fact:'Su actividad contribuye al control de la posición y los giros de la cabeza. Son músculos distintos, agrupados aquí para el estudio.',sources:['backmuscles','bodyparts']},
  {id:'levatorscapulae',name:'Elevador de la escápula',type:'MÚSCULO',text:'Se extiende desde vértebras cervicales superiores hasta el borde medial superior de la escápula.',fact:'Eleva la escápula y contribuye a su rotación inferior.',sources:['upperlimb','bodyparts']},
  {id:'hiprotators',name:'Rotadores profundos de cadera',type:'MÚSCULOS',text:'Grupo posterior profundo que incluye piriforme, obturadores y cuadrado femoral, entre pelvis y fémur proximal.',fact:'Contribuyen a rotación lateral de cadera y a estabilizar la cabeza femoral; sus acciones dependen de la posición de la cadera.',sources:['hipmuscles','bodyparts']},
  {id:'teresmajor',name:'Redondo mayor',type:'MÚSCULO',text:'Va de la región inferior posterior de la escápula al húmero proximal, por debajo del redondo menor.',fact:'Ayuda a extender, aducir y rotar medialmente el brazo. No forma parte del manguito rotador.',sources:['upperlimb','bodyparts']},
  {id:'coracobrachialis',name:'Coracobraquial',type:'MÚSCULO',text:'Se extiende desde la apófisis coracoides hasta la cara medial del húmero.',fact:'Contribuye a flexión y aducción del brazo en la articulación del hombro.',sources:['upperlimb','bodyparts']},
  {id:'pronators',name:'Pronadores del antebrazo',type:'MÚSCULOS',text:'Pronador redondo y pronador cuadrado actúan entre húmero o cúbito y radio para girar el antebrazo.',fact:'La pronación lleva la palma hacia atrás en la posición anatómica. El control radiocubital ilustra el giro aproximado del radio.',sources:['upperlimb','bodyparts']},
  {id:'wristflexors',name:'Flexores de muñeca y dedos',type:'MÚSCULOS',text:'Grupo anterior del antebrazo que incluye flexores radiales y cubitales del carpo y flexores de los dedos.',fact:'Sus tendones cruzan la muñeca para flexionar la mano o los dedos; cada músculo tiene una acción específica.',sources:['upperlimb','bodyparts']},
  {id:'wristextensors',name:'Extensores de muñeca y dedos',type:'MÚSCULOS',text:'Grupo posterior del antebrazo que incluye extensores radiales y cubitales del carpo y extensores digitales.',fact:'Extienden la muñeca o los dedos y ayudan a estabilizar la mano durante la prensión.',sources:['upperlimb','bodyparts']},
  {id:'adductors',name:'Aductores del muslo',type:'MÚSCULOS',text:'Grupo medial del muslo que incluye pectíneo, aductor breve, aductor mayor y grácil.',fact:'Llevan el muslo hacia la línea media; también pueden colaborar en otras acciones según el músculo y la postura.',sources:['limbmuscles','bodyparts']},
  {id:'lowerlegmuscles',name:'Músculos de la pierna',type:'MÚSCULOS',text:'Incluye fibulares, tibial posterior y flexores o extensores largos de los dedos y del dedo gordo.',fact:'Participan en el control del tobillo y del pie, incluida la flexión plantar, dorsiflexión y movimientos de los dedos.',sources:['limbmuscles','bodyparts']},
  {id:'popliteus',name:'Poplíteo',type:'MÚSCULO',text:'Pequeño músculo profundo de la cara posterior de la rodilla, entre fémur lateral y tibia posterior.',fact:'Ayuda a iniciar la flexión de la rodilla desde la extensión y a controlar su rotación.',sources:['limbmuscles','bodyparts']},
  {id:'footmuscles',name:'Músculos intrínsecos del pie',type:'MÚSCULOS',text:'Grupo situado dentro del pie; las mallas incluyen abductor del dedo gordo, flexor corto de los dedos y extensor corto del dedo gordo.',fact:'Contribuyen a mover los dedos y a mantener el control fino del apoyo.',sources:['foot','bodyparts']},
  {id:'scalenes',name:'Escalenos',type:'MÚSCULOS',text:'Escaleno anterior, medio y posterior ocupan la región lateral profunda del cuello, desde vértebras cervicales hasta las primeras costillas.',fact:'Participan en inclinación y flexión cervical; también pueden ayudar a elevar costillas durante la inspiración.',sources:['backmuscles','bodyparts']},
  {id:'subclavius',name:'Subclavio',type:'MÚSCULO',text:'Músculo corto entre primera costilla y cara inferior de la clavícula.',fact:'Ayuda a estabilizar y deprimir la clavícula.',sources:['subclavius','bodyparts']},
  {id:'serratusposterior',name:'Serratos posteriores',type:'MÚSCULOS',text:'El serrato posterior superior y el inferior son músculos delgados profundos de la espalda que llegan a las costillas.',fact:'Sus acciones costales son pequeñas y varían con la respiración y la postura.',sources:['serratusposterior','bodyparts']},
  {id:'anconeus',name:'Ancóneo',type:'MÚSCULO',text:'Pequeño músculo posterior del codo entre epicóndilo lateral del húmero y cúbito proximal.',fact:'Colabora con el tríceps en la extensión y estabiliza el codo.',sources:['upperlimb','bodyparts']},
  {id:'supinator',name:'Supinador',type:'MÚSCULO',text:'Músculo profundo del antebrazo proximal que envuelve la región superior del radio.',fact:'Gira el radio para orientar la palma hacia delante en la posición anatómica; el bíceps también puede supinar.',sources:['upperlimb','bodyparts']},
  {id:'thumbtendons',name:'Músculos largos del pulgar',type:'MÚSCULOS',text:'Flexor largo y extensores largo y corto del pulgar tienen vientres en el antebrazo y tendones que cruzan hacia el pulgar.',fact:'Permiten flexión o extensión del pulgar; sus mallas se agrupan para poder ocultarlas y explorar capas.',sources:['upperlimb','bodyparts']},
  {id:'handintrinsics',name:'Intrínsecos de la mano',type:'MÚSCULOS',text:'Incluyen oponente del pulgar, interóseos y lumbricales, situados dentro de la mano.',fact:'Coordinan movimientos finos de dedos y pulgar; los interóseos separan o aproximan dedos.',sources:['upperlimb','bodyparts']},
  {id:'neckjoint',name:'Complejo cervical',type:'ARTICULACIÓN',text:'La unión del occipital con el atlas favorece flexión y extensión; la unión entre atlas y axis permite gran parte de la rotación cervical.',fact:'La animación usa un único pivote didáctico y no representa cada vértebra cervical.',sources:['joints','jointtypes']},
  {id:'radioulnarjoint',name:'Articulaciones radiocubitales',type:'ARTICULACIÓN',text:'Articulaciones sinoviales de tipo pivote entre radio y cúbito, cerca del codo y la muñeca.',fact:'La pronación y supinación hacen girar el radio alrededor del cúbito; el visor usa un eje aproximado.',sources:['joints','jointtypes','motions']},
  {id:'deepneck',name:'Músculos profundos suboccipitales y cervicales',type:'MÚSCULOS',text:'Incluye rectos y oblicuos suboccipitales, largo de la cabeza y rotadores cervicales. Rodean la unión craneocervical y participan en ajustes finos de la cabeza.',fact:'Su malla sigue la cabeza con una aproximación rígida; no representa el movimiento independiente de cada vértebra.',sources:['headmuscles','bodyparts']},
  {id:'suprahyoid',name:'Músculos suprahioideos',type:'MÚSCULOS',text:'Digástrico, estilohioideo, milohioideo y genihioideo conectan mandíbula, hioides o base craneal. Contribuyen a deglución y apertura mandibular según qué segmento esté fijo.',fact:'La apertura mandibular real también desplaza los cóndilos; esta visualización aproxima el gesto.',sources:['headmuscles','bodyparts']},
  {id:'eyemuscles',name:'Músculos extrínsecos del ojo',type:'MÚSCULOS',text:'Rectos y oblicuos orbitarios orientan el globo ocular; el elevador del párpado superior abre el párpado. Son piezas pequeñas dentro de la órbita.',fact:'El visor permite acercarse a las mallas, pero todavía no anima el globo ocular por separado.',sources:['headmuscles','bodyparts']},
  {id:'pharynxmuscles',name:'Músculos de faringe y paladar',type:'MÚSCULOS',text:'Los constrictores faríngeos y músculos palatinos ayudan a transportar el bolo durante la deglución y a cerrar el paso hacia la nariz.',fact:'Se muestran por ubicación; la deglución no se simula.',sources:['headmuscles','bodyparts']},
  {id:'larynxmuscles',name:'Músculos intrínsecos de la laringe',type:'MÚSCULOS',text:'Cricoaritenoideos, tiroaritenoideo, vocal y cricotiroideo modifican la posición y tensión de los pliegues vocales.',fact:'Las mallas no modelan fonación, flujo de aire ni vibración vocal.',sources:['headmuscles','bodyparts']},
  {id:'tonguemuscles',name:'Músculos de la lengua',type:'MÚSCULOS',text:'Geniogloso e hiogloso forman parte del sistema extrínseco que cambia la posición de la lengua durante habla y deglución.',fact:'El movimiento fino de la lengua no está animado.',sources:['headmuscles','bodyparts']},
  {id:'pelvicfloor',name:'Suelo pélvico',type:'MÚSCULOS',text:'Pubococcígeo, puborrectal, iliococcígeo y coccígeo constituyen capas profundas que sostienen vísceras pélvicas y participan en continencia.',fact:'Estas mallas se pueden aislar para verlas bajo la pelvis; no se simula su contracción.',sources:['pelvicfloor','bodyparts']},
  {id:'deepback',name:'Músculos profundos vertebrales',type:'MÚSCULOS',text:'Espinoso torácico, interespinosos y rotadores lumbares son componentes pequeños próximos a las vértebras.',fact:'Contribuyen al control segmentario y la postura; la columna de este visor se mueve como unidad.',sources:['headmuscles','bodyparts']},
  {id:'thoracicdeep',name:'Músculos profundos del tórax',type:'MÚSCULOS',text:'Transverso torácico y elevadores de las costillas se sitúan junto a la cara interna torácica o entre vértebras y costillas.',fact:'La respiración y el movimiento individual de las costillas no se animan.',sources:['axialmuscles','bodyparts']},
  {id:'diaphragm',name:'Diafragma',type:'MÚSCULO',text:'Amplia cúpula músculotendinosa que separa tórax y abdomen y es principal motor de la inspiración.',fact:'Se ve como malla anatómica, sin simular sus cambios de forma durante la respiración.',sources:['pelvicfloor','bodyparts']},
  {id:'sesamoids',name:'Sesamoideos del pie',type:'HUESOS',text:'Pequeños huesos dentro de tendones junto a la cabeza del primer metatarsiano. La fuente ofrece dos piezas de malla por lado.',fact:'No deben confundirse las 206 mallas óseas del visor con el número de huesos del esqueleto adulto.',sources:['footbones','bodyparts']}
